    "author": "",
    "description": "36氪获悉，中信证券研报称，过去20年，房企拿地的成功关键在于人弃我取，这种逆周期操作的背后一般是更通畅的融资渠道。但未来，相信随着开发端的精品化和定制化，地块位置和规划条件的重要性，会逐渐压过拿地时间点的重要性。中信证券认为，拿地可能成为品质开发的关键环节，土地市场的景气度可能进一步分化。",
