    "title": "厄尔尼诺扰动，“糖”股期联袂上涨",
    "link": "https://36kr.com/newsflashes/3975453310956040?f=rss",
    "pub_date": "2026-09-09 08:40:13",
    "author": "",
    "description": "9月8日，A股市场涉“糖”概念股涨声一片。当天中粮糖业、*ST广糖等糖业股强势涨停；代糖概念板块亦大涨，三元生物大涨超14%，华康股份、中粮科技、红棉股份、保龄宝涨停。期货市场上，国内白糖期货主力合约继续上行，盘中一度创出最近两个月新高，该合约已连续多个交易日上涨。有专业人士认为，厄尔尼诺导致的欧盟甜菜减产、印度和泰国的减产预期是本轮行情最核心的驱动力量。“厄尔尼诺导致的欧盟甜菜减产、印度和泰国的减产预期是本轮行情最核心的驱动力量，之后…",
