    "description": "8月底，住房和城乡建设部、中国人民银行、国家金融监管总局等多个部门打出政策“组合拳”，推动加快构建房地产发展新模式，新政效应持续释放。通过走访深圳新房和二手房市场。“自8月底以来，我们店的带看量与8月中旬相比上升近20%。”付经理是深圳市罗湖区翠竹片区一位资深房产中介经理，在他看来，当前购房者心态整体趋于平稳，置业偏好集中在低总价刚需物业与优质学区房，多数人仍在等待政策“组合拳”的配套细则进一步落地。（证券时报）",
