    "description": "中新网9月9日电 据中央气象台网站消息，国内方面，昨日，四川、青海等地出现强降雨；内蒙古、辽宁、河南出现大风降温。预计未来三天，冷空气将继续影响北方地区，陕西、甘肃、宁夏、四川等地有较强降雨，需防范局地强降雨可能引发的山洪、地质灾害、中小河流洪水等次生灾害。",
