    "description": "随着鲁迅文学奖8月在上海颁出，八九月间上海各文化场馆持续推出各类鲁迅主题文化活动。9月5日下午，“视觉的、感铭的、国际的活字：鲁迅与世界电影”活动在思南文学之家举办。华东师范大学中文系教授陈子善、华东师范大学国际汉语文化学院教授毛尖、上海大学上海电影学院教授刘海波、上海交通大学人文学院副教授王宇平四位嘉宾从鲁迅的观影记录、电影趣味与理论翻译等角度切入，带领现场读者通过银幕与生活，看见一个有血有肉的鲁迅。本次讲座也是2026鲁迅文学周系列…",
    "content": "随着鲁迅文学奖8月在上海颁出，八九月间上海各文化场馆持续推出各类鲁迅主题文化活动。9月5日下午，“视觉的、感铭的、国际的活字：鲁迅与世界电影”活动在思南文学之家举办。华东师范大学中文系教授陈子善、华东师范大学国际汉语文化学院教授毛尖、上海大学上海电影学院教授刘海波、上海交通大学人文学院副教授王宇平四位嘉宾从鲁迅的观影记录、电影趣味与理论翻译等角度切入，带领现场读者通过银幕与生活，看见一个有血有肉的鲁迅。本次讲座也是2026鲁迅文学周系列活动之一。 鲁迅本人是一位“资深影迷”。讲座开篇，陈子善梳理了鲁迅的“观影年谱”…"
