    "content": "据中国新闻网援引董建华办公室2026年9月9日凌晨发布的消息，全国政协前副主席、香港特别行政区首任行政长官董建华，于2026年9月8日晚10时许，在亲人陪伴下于医院安详辞世，享年89岁。"
