    "description": "最近，12345热线因为几则新闻意外成为舆论焦点——据四川日报微信公众号等媒体报道，某地近日连续举办多场演唱会，短短十天，当地12345热线接收近5万件相关诉求，其中超过八成围绕舞台安排展开。前段时间，一则“月亮太亮影响睡觉，市民拨打12345投诉”的新闻，也让不少网友哭笑不得。两件事放在一起看，难免让人想问一句：12345到底是干什么的？",
