    "content": "美股三大指数全线收跌。 Wind数据显示，截至当地时间9月8日收盘，道指跌1.18%报52786.07点，标普500指数跌0.58%报7673.52点，纳指跌0.32%报26421.41点。 其中，科技股表现虽有所分化，但普遍承压。一方面，大型科技股普跌，万得美国科技七巨头指数跌0.74%。 个股方面，英伟达跌超2%，苹果、微软跌逾1%，亚马逊跌0.60%，脸书跌0.53%；特斯拉则涨近4%。 分析人士认为，随着中东地缘冲突升级加剧，叠加市场对美国通胀反复、债务高企、美债减持等因素的担忧，推动市场风险偏好持续回落，…"
