    "content": "新华社基辅9月8日电（记者李东旭）据乌克兰基辅市和基辅州方面8日消息，俄罗斯军方对该地区的空袭致死人数已升至7人。 乌克兰首都基辅市军事管理局8日在社交媒体发文说，截至当晚，俄军凌晨对基辅市发动的空袭已造成5人死亡、29人受伤。 基辅州军事管理局8日晚在社交媒体发文说，俄军当天对该州发动了无人机袭击，袭击导致两人死亡、三人受伤，该州布昌斯基区的仓库区遭袭后起火，截至晚间，大火被扑灭。 据乌空军8日在社交媒体发布消息，7日晚至8日凌晨，俄军从布良斯克州、沃罗涅日州、沃洛格达州、奥廖尔州、克拉斯诺达尔边疆区和克里米亚向…"
