    "description": "近日，德国东部萨安州议会选举中，极右翼的德国选择党高票获胜。二战以来，从未有极右翼政党在德国的州一级获得如此规模的支持。这对德国乃至欧洲意味着什么？澎湃新闻记者连线同济大学德国研究中心主任郑春荣，以及正在德国的上海外国语大学欧洲研究所执行所长胡春春进行了解读。",
