    "author": "澎湃新闻记者 黄粤涵",
    "description": "“和两年前相比，最直观的感觉就是发展速度很快。”宝石商人陈琳回忆道。两年前她初到阿富汗首都喀布尔考察时，街头出租车极度匮乏。如今，喀布尔街头不仅出租车“肉眼可见地变多”且车身颜色统一，沿街更是一片大兴土木的景象，“步行十几分钟，就能看到一栋拔地而起的新楼。” 五年前的9月7日，塔利班宣布在阿富汗组建临时政府，曾承诺将确保国家实现“持久和平、繁荣与发展”。但复苏的表象之下，普通阿富汗人感受到的却是生存寒冬。联合国数据显示，目前该国四分之三…",
    "content": "“和两年前相比，最直观的感觉就是发展速度很快。”宝石商人陈琳回忆道。两年前她初到阿富汗首都喀布尔考察时，街头出租车极度匮乏。如今，喀布尔街头不仅出租车“肉眼可见地变多”且车身颜色统一，沿街更是一片大兴土木的景象，“步行十几分钟，就能看到一栋拔地而起的新楼。” 五年前的9月7日，塔利班宣布在阿富汗组建临时政府，曾承诺将确保国家实现“持久和平、繁荣与发展”。但复苏的表象之下，普通阿富汗人感受到的却是生存寒冬。联合国数据显示，目前该国四分之三的人口无法满足基本生存需求，失业率居高不下。 原本属于中产阶层的法蒂玛一家滑向赤…"
