    "title": "明天凌晨苹果新CEO迎来首秀，首款折叠iPhone有哪些悬念？",
    "link": "https://m.thepaper.cn/detail/34030728",
    "pub_date": "2026-09-09 06:44:31",
    "author": "澎湃新闻记者 胡含嫣",
    "description": "北京时间9月10日凌晨1点，苹果秋季发布会将在Apple Park乔布斯剧院举行，此次活动主题为“亮新篇，来耀眼”。 这是苹果新CEO约翰·特努斯（John Ternus）9月1日上任以来的首场重大发布会。9月2日，特努斯在公司内部信中写道：“我对我们正在筹备的一切感到无比兴奋。我们下周将有一场规模巨大的发布活动，将会非常精彩。我同样对之后将要发生的一切感到兴奋。” 秋季发布会是苹果一年之中最为重磅的产品发布活动，被果粉称为苹果“春晚”…",
    "content": "北京时间9月10日凌晨1点，苹果秋季发布会将在Apple Park乔布斯剧院举行，此次活动主题为“亮新篇，来耀眼”。 这是苹果新CEO约翰·特努斯（John Ternus）9月1日上任以来的首场重大发布会。9月2日，特努斯在公司内部信中写道：“我对我们正在筹备的一切感到无比兴奋。我们下周将有一场规模巨大的发布活动，将会非常精彩。我同样对之后将要发生的一切感到兴奋。” 秋季发布会是苹果一年之中最为重磅的产品发布活动，被果粉称为苹果“春晚”。为苹果贡献主要营收的iPhone系列将迎来更新换代，而今年外界最大的期待则是苹…"
