    "content": "新华社纽约9月8日电（记者刘亚南）美国总统特朗普8日在社交媒体上发文称，他已指示美国总务管理局与美国贸易代表办公室合作，采取一切必要措施把加拿大产品排除出美政府采购计划，直至加方对美农民和企业恢复“公平的互惠”。 特朗普称，“多年来加拿大一直在占我们的便宜”，加拿大联邦及省级政府禁止美国小企业和公司进入其政府采购市场，而加拿大却可以广泛进入美国庞大的政府采购市场。 他说：“这不是对等互惠，这是加拿大的一个贸易骗局。从现在开始，没有对等互惠，就没有市场准入。” 截至记者发稿时，美国白宫、总务管理局以及贸易代表办公室尚…"
