    "content": "新华社华盛顿9月8日电（记者黄强 徐剑梅）据美国有线电视新闻网8日援引两名美官员的话报道，美军当天在伊朗哈尔克岛附近袭击多艘伊朗油轮。 报道说，作为对伊朗企图用导弹袭击美军舰的回应，美军袭击了与伊朗伊斯兰革命卫队相关的油轮。 截至发稿时，美军中央司令部尚未发布相关消息。 另据美国《华尔街日报》8日报道，美官员称，伊朗上周末向美国一艘航空母舰和一艘导弹驱逐舰发射弹道导弹后，7日再次袭击美军舰。这些袭击未击中美方舰艇，但此类行动或导致冲突升级。 美军中央司令部5日发表声明称，美军击沉了一艘伊朗油轮，并使两艘伊朗油轮“永…"
