    "description": "新华社渥太华9月8日电（记者林威）加拿大政府针对美国加征关税的反制措施8日凌晨正式生效后，加拿大总理卡尼发表全国视频讲话，动员全民团结应对加美贸易战。 卡尼以冰球运动为比喻说：“每当我们选择购买加拿大商品、在加拿大境内旅行时，我们都在传递一个信号——在这个国家，没有人在看台上（观望），4000万名加拿大人全都在冰面上（拼搏）。” 卡尼表示，当前最根本的问题是美国“希望我们对他们更加依赖，而不是更加独立。在太多领域，他们追求依附而非平等的…",
    "content": "新华社渥太华9月8日电（记者林威）加拿大政府针对美国加征关税的反制措施8日凌晨正式生效后，加拿大总理卡尼发表全国视频讲话，动员全民团结应对加美贸易战。 卡尼以冰球运动为比喻说：“每当我们选择购买加拿大商品、在加拿大境内旅行时，我们都在传递一个信号——在这个国家，没有人在看台上（观望），4000万名加拿大人全都在冰面上（拼搏）。” 卡尼表示，当前最根本的问题是美国“希望我们对他们更加依赖，而不是更加独立。在太多领域，他们追求依附而非平等的经济伙伴关系”。 卡尼说，为减少对美国的依赖，加拿大会有所付出，但任何行动都有代…"
