    "content": "新华社联合国9月8日电（记者尚绪谦）联合国秘书长古特雷斯的发言人迪雅里克8日称，古特雷斯希望最近的外交努力能够使俄罗斯和乌克兰恢复谈判。 迪雅里克在8日的例行记者吹风会上说，古特雷斯对于包括美国特使访问莫斯科和基辅在内的外交努力感到鼓舞。他希望新的倡议能够使得乌克兰和俄罗斯恢复谈判，为立即无条件全面停火以及达成符合国际法的公平、全面、持久和平铺平道路。联合国方面愿意为此提供协助。 迪雅里克说，与此同时，古特雷斯对于俄乌两国平民和民用设施不断遭到袭击表示严重关切。古特雷斯呼吁立即停止攻击平民和民用设施，敦促双方为持续…"
