    "content": "新华社巴黎9月8日电（记者乔本孝）据法国总统府官网8日消息，英国首相伯纳姆、法国总统马克龙、加拿大总理卡尼当天发表联合声明，谴责以色列在约旦河西岸地区扩张，呼吁落实“两国方案”。 声明说，通过“两国方案”解决巴以冲突，对中东及更广泛地区的和平、稳定、安全至关重要，也符合英法加三国根本利益。约旦河西岸以色列定居点系统性扩张，包括以色列政府“E1区”定居点建设决定，以及犹太人定居者暴力行为，对和平愿景构成直接且紧迫的威胁。 声明说，英法加三国已正式承认巴勒斯坦国，致力于维护“两国方案”。根据国际法，这些定居点属于非法机…"
