    "content": "新华社拉姆安拉9月8日电（记者赵伟宏）巴勒斯坦总统府8日表示，欢迎法国、英国、加拿大等12国外长有关拟限制与约旦河西岸以色列定居点商品贸易的联合声明。 据巴勒斯坦通讯社报道，巴勒斯坦总统府发表声明说，此举是追究定居点活动责任的重要步骤，体现了对在欧洲层面采取类似措施的支持。 声明呼吁相关12个国家、欧盟及国际社会将相关立场转化为具有约束力的措施，包括禁止与定居点进行贸易往来、对极端定居者及其支持者实施制裁，并追究以色列政府责任。 声明敦促以色列政府立即停止定居点活动、取消“E1区”定居点项目招标、制止定居者袭击活动…"
