    "content": "新华社开罗9月8日电（记者张猛）喀土穆消息：苏丹民间机构8日说，该国中部北科尔多凡州乌姆鲁瓦巴市当天下午发生无人机袭击，造成13人死亡、22人受伤。 民间机构“苏丹医生网”在一份声明中说，袭击系准军事组织快速支援部队所为，目标是乌姆鲁瓦巴市民用设施，发生在人员活动密集的时候。 苏丹民间机构“紧急律师倡议”发表声明，谴责快速支援部队无人机袭击乌姆鲁瓦巴市法院，称这一行为严重违反国际人道主义法，呼吁苏丹冲突各方保护平民及民用设施，追究肇事者责任。 目击者告诉新华社记者，当天13时左右，一架无人机向乌姆鲁瓦巴市初级法院发…"
