    "description": "新华社纽约9月8日电（记者刘亚南）美国财政部8日发布公告，把27家伊朗航空公司及其他多个公司列入“特别指定国民清单”以实施制裁。 美国政府早在2011年就已制裁伊朗马汉航空，上述举措意味着伊朗所有航空公司均受到美方制裁。 美国财政部外国资产控制办公室当日还把位于土耳其、马来西亚和哈萨克斯坦的4家从事货运服务和销售代理的企业列入制裁清单。美方指认这4家企业为马汉航空相关运营和采购提供便利。 同时，外国资产控制办公室暂停三项与伊朗相关的航空…",
    "content": "新华社纽约9月8日电（记者刘亚南）美国财政部8日发布公告，把27家伊朗航空公司及其他多个公司列入“特别指定国民清单”以实施制裁。 美国政府早在2011年就已制裁伊朗马汉航空，上述举措意味着伊朗所有航空公司均受到美方制裁。 美国财政部外国资产控制办公室当日还把位于土耳其、马来西亚和哈萨克斯坦的4家从事货运服务和销售代理的企业列入制裁清单。美方指认这4家企业为马汉航空相关运营和采购提供便利。 同时，外国资产控制办公室暂停三项与伊朗相关的航空授权，涉及航班飞越伊朗领空等。 此外，美财政部下属金融犯罪执法网络当日发布警示信…"
