    "content": "新华社莫斯科9月8日电（记者栾海）俄罗斯总统普京与美国总统特朗普8日通电话，重点讨论解决乌克兰问题。普京在通话中指出美方可采取哪些措施推动尽早结束特别军事行动。特朗普则表示有意在任期内推动乌克兰问题的解决取得突破。 据俄总统网站8日发布的消息，俄总统助理乌沙科夫说，此次通话持续一小时，俄美总统以相互尊重和务实态度，就美代表团日前对俄罗斯和乌克兰的访问成果交换意见，积极评价美代表团此次访俄成果，并表示将继续通过这类渠道保持沟通。 乌沙科夫说，此次通话的焦点是解决乌克兰问题，特朗普明确表达尽早结束俄乌冲突的愿望，认为冲…"
