    "author": "崔可欣,张百慧",
    "description": "新华社巴黎9月8日电（记者张百慧 崔可欣）位于法国东南部城市滨海卡涅的雷诺阿博物馆8日清晨4幅画作遭窃，截至目前其中两幅在博物馆的花园内被找到。 据法国媒体报道，盗窃案发生于当天6时前不久，作案时间不到5分钟。法媒援引警方消息说，作案者先是用工具割断栅栏，然后打破玻璃，进入博物馆。两名窃贼共盗走4幅画作，其中《斯蒂芬·皮雄夫人的画像》和《阅读中的可可》两幅在其逃离现场过程中被丢弃在博物馆所在园区围栏内。 据报道，目前仍有《科隆纳·罗马诺…",
    "content": "新华社巴黎9月8日电（记者张百慧 崔可欣）位于法国东南部城市滨海卡涅的雷诺阿博物馆8日清晨4幅画作遭窃，截至目前其中两幅在博物馆的花园内被找到。 据法国媒体报道，盗窃案发生于当天6时前不久，作案时间不到5分钟。法媒援引警方消息说，作案者先是用工具割断栅栏，然后打破玻璃，进入博物馆。两名窃贼共盗走4幅画作，其中《斯蒂芬·皮雄夫人的画像》和《阅读中的可可》两幅在其逃离现场过程中被丢弃在博物馆所在园区围栏内。 据报道，目前仍有《科隆纳·罗马诺夫人》和《井边少女》两幅作品下落不明。 目前，警方仍在追捕嫌疑人。雷诺阿博物馆处…"
