    "author": "徐皓夫,姚兵",
    "description": "新华社开罗9月8日电（记者徐皓夫 姚兵）第二届埃及国际航展8日在埃及地中海城市阿拉曼国际机场开幕，埃及总统塞西出席开幕式。 据主办方介绍，本届航展为期三天，旨在打造展示航空航天最新技术成果、促进交流的国际平台，推动非洲和中东地区在国防、航天和商用航空领域的国际合作。航展预计将吸引来自约50个国家和地区的250多家航空航天、防务、导航和空间技术领域的企业和机构参展。航展期间将举行50多场飞行表演，展出100多架航空器，并吸引多国官方代表团…",
    "content": "新华社开罗9月8日电（记者徐皓夫 姚兵）第二届埃及国际航展8日在埃及地中海城市阿拉曼国际机场开幕，埃及总统塞西出席开幕式。 据主办方介绍，本届航展为期三天，旨在打造展示航空航天最新技术成果、促进交流的国际平台，推动非洲和中东地区在国防、航天和商用航空领域的国际合作。航展预计将吸引来自约50个国家和地区的250多家航空航天、防务、导航和空间技术领域的企业和机构参展。航展期间将举行50多场飞行表演，展出100多架航空器，并吸引多国官方代表团和约1.2万名观众。 开幕式上，埃及空军与来自俄罗斯、西班牙、土耳其、沙特阿拉伯…"
