    "content": "开栏的话： 民族复兴的浩荡征程中，我们即将迎来中国工农红军长征胜利90周年的光辉节点。 这一惊天动地的革命壮举，是中国共产党和红军谱写的壮丽史诗，是中华民族伟大复兴历史进程中的巍峨丰碑。中国共产党和红军以非凡的智慧、巨大的牺牲，完成了人类历史上的伟大远征，铸就了伟大长征精神，也为后人留下了永不枯竭的精神源泉。 按照有关安排，即日起，新华社推出“赓续长征精神 奋进复兴征程”专栏，组织记者深入采访长征沿线重要地标、纪念场馆、老区乡村，追寻红色足迹，记录时代变迁，重温那场气壮山河的伟大远征，展现长征精神的薪火相传，激励亿…"
