    "content": "新华社北京9月8日电 冰岛外交部8日宣布，冰岛外交部长索尔杰尔迪·卡特琳·贡纳尔斯多蒂尔7日召见美国驻冰岛大使比利·朗，就美国总统特朗普发帖将冰岛“圈入美国版图”一事表达不满。 特朗普7日在“真实社交”平台上发布一张“地图”，显示美国国旗的红白条纹覆盖了墨西哥、加勒比地区、加拿大以及格陵兰岛和冰岛等，并标注文字“美利坚合众国”。 据冰岛国家广播局报道，冰岛外长向美国大使明确表达了冰岛立场，即上述帖文“十分不合适”。 这是2025年3月14日拍摄的冰岛首都雷克雅未克市区景象。新华社记者张帆摄 比利·朗上月正式就任美国…"
