    "content": "新华社昆明9月8日电 题：云南宣威：百年老火腿 蹚出新生意 新华社记者吉哲鹏、陈欣波 中秋临近，云南的火腿月饼迎来销售旺季。日前，记者走进远近闻名的“中国火腿文化之乡”云南省宣威市，实地探访多家火腿企业，只见车间里生产线满负荷运转，工人们正加紧赶制月饼，供应节日市场。忙碌之余，记者也注意到一个新变化：生食火腿等创新品类的市场正愈加成熟，为这百年老味道蹚出了一条新路子。 工作人员在宣威火腿产业园一家火腿龙头企业月饼生产车间制作火腿月饼（9月3日摄）。新华社记者陈欣波 摄 在宣威火腿产业园一家火腿龙头企业的库房，金属挂…"
