    "content": "新华社东京9月8日电（记者李子越 陈泽安）据日本共同社8日报道，在日本冲绳县因当地美军基地周边检测出有机氟化合物（PFAS）而申请进入基地调查但遭美方拒绝一事中，日本防卫省去年12月公布美方答复时，隐瞒了美方曾表示“强烈推测污染来源于基地”这一内容。 报道称，冲绳县美军嘉手纳基地、普天间机场等周边地区此前曾检测出PFAS。为查明污染源，冲绳县自2016年以来先后4次向美方申请进入基地调查，但均未获许可。2025年12月，日本防卫省对外公布美方答复时称，美方以“缺少明确表明美军基地是污染源的样本调查数据”等为由拒绝了…"
