    "content": "36氪从多位产业人士处了解到，头部新势力品牌理想汽车，将引入第三家动力电池供应商——中创新航。按理想汽车的初步构想，中创新航将率先上车理想的纯电车。 另有知情人士表示，理想i6或将是首款搭载中创新航产品的车型。 2026款理想i6也出现在最新的工信部公告中，两种电池总成的生产企业都是山东理想汽车电池有限公司，电芯制造商分别是欣旺达和中创新航。而2025款理想i6的电池供应商是宁德时代和欣旺达。 理想i6是理想的主销车型，今年上半年交付超过12万辆，为理想贡献了超50%销量。 中创新航是国内出货量仅次于宁德时代、比亚…"
