    "author": "林凯,宓盈婷",
    "description": "“从福建最远的地方开始，一直到遥远的陕西北道路的尽头为止”。著名作家埃德加·斯诺在《西行漫记》一书中，这样描述当年红军的英雄史——长征。其中，“福建最远的地方”指的就是福建宁化。 如今，这个万里“红飘带”最远的起点依旧能听到历史的回响，号角声穿越时空仍然嘹亮，红星照耀下的中国永远朝气蓬勃。 今年是红军长征胜利90周年，和新华社记者一起，寻迹长征。 记者：宓盈婷、林凯 编导：于跃 新华社音视频部制作",
    "content": "“从福建最远的地方开始，一直到遥远的陕西北道路的尽头为止”。著名作家埃德加·斯诺在《西行漫记》一书中，这样描述当年红军的英雄史——长征。其中，“福建最远的地方”指的就是福建宁化。 如今，这个万里“红飘带”最远的起点依旧能听到历史的回响，号角声穿越时空仍然嘹亮，红星照耀下的中国永远朝气蓬勃。 今年是红军长征胜利90周年，和新华社记者一起，寻迹长征。 记者：宓盈婷、林凯 编导：于跃 新华社音视频部制作"
