    "description": "新华社莫斯科9月8日电（记者刘恺）俄罗斯外交部发言人扎哈罗娃8日说，俄方将对匈牙利驱逐10名俄外交人员作出强硬回应。 俄新社援引扎哈罗娃的话报道，针对匈牙利驱逐10名俄罗斯外交人员一事，俄方回应将“强硬且令匈方痛苦”。她没有具体说明俄方将作出何种回应。 俄联邦委员会（议会上院）副主席科萨切夫表示，任何驱逐行为都是不友好的，这样的“集体”驱逐更是极其不友好的对抗性举动，是公开的挑战，必然引发俄方对等回应。 匈牙利副总理兼外交部长奥尔班·奥…",
    "content": "新华社莫斯科9月8日电（记者刘恺）俄罗斯外交部发言人扎哈罗娃8日说，俄方将对匈牙利驱逐10名俄外交人员作出强硬回应。 俄新社援引扎哈罗娃的话报道，针对匈牙利驱逐10名俄罗斯外交人员一事，俄方回应将“强硬且令匈方痛苦”。她没有具体说明俄方将作出何种回应。 俄联邦委员会（议会上院）副主席科萨切夫表示，任何驱逐行为都是不友好的，这样的“集体”驱逐更是极其不友好的对抗性举动，是公开的挑战，必然引发俄方对等回应。 匈牙利副总理兼外交部长奥尔班·奥妮道8日在社交媒体发文说，匈牙利政府决定驱逐10名俄罗斯外交人员。匈牙利有关部门…"
