    "title": "马来西亚一架直升机坠毁 机上人员伤亡不明",
    "link": "http://www.news.cn/20260908/6c8740b7283a47dbaf33ed53488161a7/c.html",
    "pub_date": "2026-09-08 21:37:34",
    "author": "袁睿,何光海",
    "description": "新华社吉隆坡9月8日电（记者袁睿 何光海）马来西亚民航局8日表示，一架载有5人的直升机当天在马来西亚沙捞越州龙巴朗机场附近坠毁。目前机上人员伤亡情况不明。 据马来西亚民航局发表的声明，该局当天15时58分接到飞行信息服务部门报告，获悉这起事故。失事直升机当时在执行医疗飞行服务任务，机上包括飞行员在内共有5人。 沙捞越州警察总监穆罕默德·扎伊纳尔·阿卜杜拉表示，相关部门目前正在展开搜救行动，并对事故原因进行调查。",
    "content": "新华社吉隆坡9月8日电（记者袁睿 何光海）马来西亚民航局8日表示，一架载有5人的直升机当天在马来西亚沙捞越州龙巴朗机场附近坠毁。目前机上人员伤亡情况不明。 据马来西亚民航局发表的声明，该局当天15时58分接到飞行信息服务部门报告，获悉这起事故。失事直升机当时在执行医疗飞行服务任务，机上包括飞行员在内共有5人。 沙捞越州警察总监穆罕默德·扎伊纳尔·阿卜杜拉表示，相关部门目前正在展开搜救行动，并对事故原因进行调查。"
