    "author": "孙少雄,王菲",
    "description": "新华社乌鲁木齐9月8日电（记者孙少雄、王菲）9月8日，国际知名人士新疆友好交流会在新疆乌鲁木齐举行。来自上海合作组织、国际劳工组织两个国际组织，以及33个国家的政府官员、工商界代表、专家学者、媒体记者等300余名中外嘉宾参会，围绕“新疆治理经验及国际意义”主题开展交流研讨。 上海合作组织秘书长叶尔梅克巴耶夫在发言中表示，自己曾多次到访新疆，亲眼见证当地发生的可喜变化。新疆在维护安全稳定方面发挥重要作用，经济合作同安全保障相辅相成，为边境…",
    "content": "新华社乌鲁木齐9月8日电（记者孙少雄、王菲）9月8日，国际知名人士新疆友好交流会在新疆乌鲁木齐举行。来自上海合作组织、国际劳工组织两个国际组织，以及33个国家的政府官员、工商界代表、专家学者、媒体记者等300余名中外嘉宾参会，围绕“新疆治理经验及国际意义”主题开展交流研讨。 上海合作组织秘书长叶尔梅克巴耶夫在发言中表示，自己曾多次到访新疆，亲眼见证当地发生的可喜变化。新疆在维护安全稳定方面发挥重要作用，经济合作同安全保障相辅相成，为边境交往与地方合作行稳致远筑牢根基。各方应当持续推进务实合作，聚焦互利共赢，推动落地…"
