    "pub_date": "2026-09-08 21:32:31",
    "author": "恩浩",
    "description": "新华社呼和浩特9月8日电（记者恩浩）初秋，内蒙古巴彦淖尔市杭锦后旗乌兰布和沙漠综合治理示范区草木繁茂，工人金美丽手握高压水枪，在沙地上打出40厘米许的孔洞，栽下梭梭苗。 “苗木根系吃水更深，地表蒸发少，种植速度提升30%，节水50%左右。”杭锦后旗林业和草原局副局长段光硕说，当地构建选苗、栽植、供水、管护全链条科技治沙体系，让苗木成活率由2022年前的53%提高到目前的90%以上。 工人用高压水枪对苗木浇水。新华社记者 李云平 摄 在兴…",
    "content": "新华社呼和浩特9月8日电（记者恩浩）初秋，内蒙古巴彦淖尔市杭锦后旗乌兰布和沙漠综合治理示范区草木繁茂，工人金美丽手握高压水枪，在沙地上打出40厘米许的孔洞，栽下梭梭苗。 “苗木根系吃水更深，地表蒸发少，种植速度提升30%，节水50%左右。”杭锦后旗林业和草原局副局长段光硕说，当地构建选苗、栽植、供水、管护全链条科技治沙体系，让苗木成活率由2022年前的53%提高到目前的90%以上。 工人用高压水枪对苗木浇水。新华社记者 李云平 摄 在兴安盟科尔沁右翼中旗高力板光伏电站，一场以科技为内核的盐碱地改造正在上演。中国科学…"
