    "author": "庞梦霞",
    "description": "新华社厦门9月8日电（记者庞梦霞）8日，由海关总署编制的2025年中国与其他金砖成员国贸易指数在第二十六届中国国际投资贸易洽谈会上发布。 指数以金砖国家领导人首次会晤的2009年为基期，2025年上升至334.14，较2024年提升32.64，实现连续10年向上攀升。 中国与其他金砖成员国贸易指数由贸易规模、贸易结构、贸易创新和贸易潜力四项指标构成，2025年上述指标值分别达到295.31、188.15、396.24和456.88。 数…",
    "content": "新华社厦门9月8日电（记者庞梦霞）8日，由海关总署编制的2025年中国与其他金砖成员国贸易指数在第二十六届中国国际投资贸易洽谈会上发布。 指数以金砖国家领导人首次会晤的2009年为基期，2025年上升至334.14，较2024年提升32.64，实现连续10年向上攀升。 中国与其他金砖成员国贸易指数由贸易规模、贸易结构、贸易创新和贸易潜力四项指标构成，2025年上述指标值分别达到295.31、188.15、396.24和456.88。 数据显示，2025年中国与其他金砖成员国有进出口记录的企业数量首次突破30万家，同…"
