    "content": "开学典礼上，巴扬手风琴一响，台下孩子的耳朵都竖了起来。 20多位小演奏者脊背挺直，目光齐刷刷投向舞台上一个清瘦的身影。这位指挥扎着丸子头，一身黑色连衣裙，抬手，落下，激昂的乐声响彻礼堂。 她叫王燕，是北京市第十九中学的音乐教师，今年50岁了，也是翼之光巴扬室内乐团的创始人。2021年，学校增设附属实验小学，6岁学键盘手风琴、半生抚琴的王燕主动请缨走进小学部，教孩子巴扬手风琴。 2000年，一场音乐会上，俄罗斯巴扬演奏大师的表演让王燕着了迷，一年后，她远赴俄罗斯学习巴扬手风琴。如今，她把琴声带给了孩子们，巴扬手风琴这…"
