    "content": "新华社呼和浩特9月8日电（记者侯维轶、魏婧宇）由中华全国新闻工作者协会和蒙古国记者协会共同主办、内蒙古自治区人民政府新闻办公室承办的第十六届中蒙新闻论坛8日在内蒙古自治区呼和浩特市举办。 本届论坛以“媒体责任：增进两国民众相互了解和友谊”为主题。中华全国新闻工作者协会党组书记崔士鑫在致辞中表示，中蒙新闻论坛自创办以来，历经十余年深耕发展，搭建起两国新闻界沟通对话的常态化重要平台。一代代新闻工作者在这里交流互鉴、携手同行，不断拉近两国民众的心灵距离，已经成为助推中蒙全面战略伙伴关系行稳致远、促进双方民心相通的特色品牌…"
