    "content": "第二十六届中国国际投资贸易洽谈会9月8日至11日在福建厦门举行。129个国家和地区、30个国际组织的1200多个政府官方机构、工商企业团组参会。在外部环境严峻复杂、世界经济发展面临更多不确定性时，更多海外客商将目光投向中国。 2018年9月，习近平总书记向第二十届投洽会致贺信，希望投洽会“办成新一轮高水平对外开放的重要平台，为推动形成全面开放新格局、建设开放型世界经济发挥积极作用”。2025年9月，习近平总书记向第二十五届投洽会致贺信指出：“中国国际投资贸易洽谈会以‘扩大双向投资 共促全球发展’为永久主题，为推动建…"
