    "content": "新华社郑州9月8日电 题：换挡升级 中原农机沃野“耕”新 新华社记者王前慧、古一平 秋日的中原大地，长风送爽，氤氲着丰收的气息。近日，新华社记者随“活力中国调研行”采访团走进河南多家农机企业，从中国一拖的生产线到国家农机装备创新中心的实验室，从中兴龙丰的智能工厂到田间地头的应用一线，一场从“制造”到“智造”的换挡升级悄然发生，北斗导航、5G通信、新能源动力、无人驾驶等新技术正推动中原农机沃野“耕”新。 走进位于洛阳的国机集团中国一拖大轮拖智能生产车间，机器人喷涂、AGV自动导引车有序运转，不到三分钟就有一台拖拉机驶…"
