    "content": "新华社香港9月8日电（记者刘媛媛）香港特区政府发展局局长宁汉豪8日表示，经过数年努力，北部都会区（北都）的规划和建设已渐见成果。其中，古洞北／粉岭北新发展区的房屋项目将会在今年起陆续入伙，洪水桥／厦村新发展区会有不同产业用地开始供应，目前在河套和沙岭已有企业进驻。 宁汉豪说，在产业发展方面，北都规划较多元化。新田科技城、河套香港园区、流浮山数码科技枢纽及沙岭数据园区合共规划超过340公顷创科用地，打造跨境协同的创科走廊；洪水桥／厦村至少有60公顷产业用地，其中约27.5公顷由洪水桥产业园公司负责建设及营运；北都有三…"
