    "title": "新华鲜报丨守护眼健康 三部门发文开出暖心“处方”",
    "link": "http://www.news.cn/20260908/02dfde01c2e8460c907f6c470345263d/c.html",
    "pub_date": "2026-09-08 20:45:19",
    "author": "李恒",
    "description": "眼健康是国民健康的重要组成部分，涉及全年龄段人群全生命周期。 记者9月8日获悉，国家卫生健康委、国家中医药局、国家疾控局近日联合印发《加快提供优质高效眼健康服务工作方案（2026-2030年》，聚焦重点人群和重点眼病，为眼健康服务工作绘制“路线图”。 根据方案，到2030年，0至6岁儿童、中小学生屈光筛查率稳步提高，全国百万人口白内障手术率超过4000，95%以上的县域可独立开展常见眼病的诊疗，各县域均能够提供白内障手术服务。 长期以来…",
    "content": "眼健康是国民健康的重要组成部分，涉及全年龄段人群全生命周期。 记者9月8日获悉，国家卫生健康委、国家中医药局、国家疾控局近日联合印发《加快提供优质高效眼健康服务工作方案（2026-2030年》，聚焦重点人群和重点眼病，为眼健康服务工作绘制“路线图”。 根据方案，到2030年，0至6岁儿童、中小学生屈光筛查率稳步提高，全国百万人口白内障手术率超过4000，95%以上的县域可独立开展常见眼病的诊疗，各县域均能够提供白内障手术服务。 长期以来，优质眼科资源多集中在城市大医院，基层和农村是薄弱环节。如何破题？ 根据方案，三…"
